'use client'

import * as React from 'react'

import { LockGlyph } from './glyphs'
import { useStrings, type StringsOverrides } from './strings'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Toggle, and `tsc --noEmit` passes on it, so the
// gate cannot catch it.
import './toggle.css'

// The shared rule sets, so the theme's press gesture reaches the pill. GSUI-118:
// the file shipped with the tokens and nothing imported it, so the classes
// matched nothing in a real install.
import './gamestage-primitives.css'

/**
 * Toggle: one setting that is on or off, and takes effect at once.
 *
 * Specimen 4b draws it in the form essentials beside the checkbox and the
 * radio, and 4d draws the same control at the end of the "Sound and haptics"
 * settings row. It is the third pressed control of that family, so it wears
 * `data-gs-elevation="raised"` and `.gs-pressable` exactly as they do: the
 * rule a player reads without being told it is that a thing typed into is
 * inset and a thing pressed is raised.
 *
 * It is a switch and not a checkbox, and the difference is not decoration. A
 * checkbox states an intention that a submit will act on later; a switch is
 * the act. Sound goes off when the thumb moves, not when a form is sent, so
 * the role is `switch` and the state is `aria-checked`.
 *
 * It performs nothing. It does not mute anything, remember a preference or
 * write to storage: the host owns the value and hands it back as a prop, so a
 * setting that fails to save on the server never shows as on.
 *
 * Locked keeps its shape and shows a padlock, per BDS-013, and stays in the
 * tab order: "available later" is something a player should be able to reach
 * and hear described. Disabled wins when both are set, for the reason button
 * gives at length: the two renderings contradict each other, and a padlock on
 * something that is never coming back tells the player the opposite of the
 * truth.
 */

export interface ToggleProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'disabled' | 'onChange' | 'value'> {
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides

  /**
   * What the setting is called, as a player reads it: "Sound". Always the
   * accessible name, and drawn beside the pill unless `labelHidden` is set.
   */
  label: string
  /**
   * Whether the setting is on. Host-driven: this renders the value it is
   * given and never keeps one of its own, so a write that fails on the server
   * cannot leave the pill saying the setting took.
   */
  checked: boolean
  /** The player moving it. Called with the value the setting would become. */
  onChange: (checked: boolean) => void
  /**
   * The words are already on screen, so draw the pill alone. Specimen 4d's
   * settings row says "Sound and haptics" in its own label and puts the
   * control at the end of it; drawing the word twice would read as two
   * settings. The label is still the accessible name.
   */
  labelHidden?: boolean
  /** Not available, and not coming back on this surface. Leaves the tab order. */
  disabled?: boolean
  /** Available later, not now. Keeps its shape, shows a padlock, stays focusable. */
  locked?: boolean
}

export function Toggle(props: ToggleProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)

  const {
    label,
    checked,
    onChange,
    labelHidden = false,
    disabled = false,
    locked = false,
    className,
    type = 'button',
    onClick,
    ...rest
  } = componentProps

  const labelId = React.useId()
  const isLocked = locked && !disabled
  const unpressable = disabled || isLocked

  return (
    <span
      className={['gs-toggle', className].filter(Boolean).join(' ')}
      data-gs-component="toggle"
      data-gs-active={checked ? 'true' : 'false'}
      data-gs-disabled={disabled ? 'true' : undefined}
      data-gs-locked={isLocked ? 'true' : undefined}
    >
      <button
        {...rest}
        type={type}
        className="gs-toggle__control gs-pressable"
        data-gs-scope="toggle"
        data-gs-part="control"
        // The rule a player reads without being told it: this is pressed, not
        // typed into, so it stands on a shelf the way field's tick box does.
        data-gs-elevation="raised"
        role="switch"
        aria-checked={checked}
        aria-labelledby={labelId}
        disabled={disabled}
        aria-disabled={unpressable || undefined}
        onClick={(event) => {
          // aria-disabled does not stop an event the way the native attribute
          // does, so a locked control has to refuse them itself. Enter and
          // Space arrive as a synthesised click on a native button, so this
          // one guard covers the thumb and the keyboard alike.
          if (unpressable) {
            event.preventDefault()
            return
          }
          onClick?.(event)
          onChange(!checked)
        }}
      >
        {/* The thumb. It is the only thing that moves, so it is the element
            that carries the motion, and motion.css stops it under reduced
            motion while the fill still changes. */}
        <span
          className="gs-toggle__thumb"
          data-gs-scope="toggle"
          data-gs-part="thumb"
          data-gs-animates="motion"
          aria-hidden="true"
        />
        {/* A padlock rather than a flat fill, and it is emphasis, so a player
            who has asked for stillness still sees that the setting is not
            theirs to change yet. */}
        {isLocked ? (
          <span
            className="gs-toggle__glyph"
            data-gs-scope="toggle"
            data-gs-part="glyph"
            data-gs-animates="emphasis"
            aria-hidden="true"
          >
            <LockGlyph />
          </span>
        ) : null}
      </button>
      {/* Content rather than aria-label, so the locked word below is part of
          the computed name instead of being replaced by it. */}
      <span
        id={labelId}
        className={labelHidden ? 'gs-toggle__announcement' : 'gs-toggle__label'}
        data-gs-scope="toggle"
        data-gs-part="label"
      >
        {label}
        {/* The state as a word, for a player who gets no padlock and no fill.
            No punctuation of its own: a comma here is copy, and the name
            computation already puts a space between the two. */}
        {isLocked ? (
          <>
            {' '}
            <span className="gs-toggle__announcement">{copy['toggle.locked']}</span>
          </>
        ) : null}
      </span>
    </span>
  )
}

/* Toggle. Every value comes from a token; nothing here is a literal colour.

   Specimen 4b draws a 72x40 pill with a 3px edge, filled on the edge colour
   when off and positive when on, and a 30px white thumb with the same edge
   that sits 2px in at either end. 4d draws the same control at the end of the
   "Sound and haptics" row. design/twins/4b.json measures ours against it. */

.gs-toggle {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-3);
  /* The words beside the pill are arbitrary length, so the row gives way
     before the control does: the label wraps, the pill keeps its size. */
  min-inline-size: 0;
}

/* The pill. 72px is the touch minimum plus space.6; there is no 72px token and
   both halves of that sum are the drawing's own measurements elsewhere. 40px
   is size.control.small exactly. */
.gs-toggle__control {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  flex: none;
  position: relative;

  inline-size: calc(var(--gs-size-touch-min) + var(--gs-space-6));
  block-size: var(--gs-size-control-small);
  padding: calc(var(--gs-space-1) / 2);

  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: 999px;
  /* Off is a neutral track and on is the accent, so on and off never read
     alike: Tom, 2026-09-28, of a dark thumb on a dark track that looked the
     same either way. */
  background: var(--gs-color-surface-raised);
  cursor: pointer;
}

/* The tap target is 48px tall however thin the pill is drawn. */
.gs-toggle__control::before {
  content: '';
  position: absolute;
  inset: calc((var(--gs-size-touch-min) - var(--gs-size-control-small)) / -2) 0;
}

.gs-toggle[data-gs-active='true'] .gs-toggle__control {
  background: var(--gs-color-interactive-solid);
  border-color: var(--gs-color-interactive-solid);
}

/* The thumb. Its height is the pill's inner box and it is square, so it
   follows the theme's stroke and the control size rather than restating the
   drawing's 30px. `box-sizing: border-box` is what makes that true: without
   it the 3px border is added outside the 100%, the thumb came out 36px in a
   34px slot, and the 4b twin caught it.

   The travel is the pill's width minus its height, which is the room left
   over however thick the theme draws the stroke and whatever the padding is:
   inner width minus thumb is (W - 2b - 2p) - (H - 2b - 2p), and the border
   and padding cancel. 72 - 40 is the drawing's 32px, from 2px in at one end
   to 2px in at the other.

   `translate` rather than `left`, so a theme changing the direction of the
   row does not need this rule rewritten, and so the move composes with the
   press gesture instead of fighting it.

   The fill is colour.ink, not white. The drawing is white, and there is no
   always-white token: base colour.onAccent is white but arcade redefines it
   to a dark navy, which drew a navy thumb on a navy pill. ink is the
   foreground token, which is what the thumb is - the thing the state is read
   from - so it stays legible against both of the pill's fills and in both
   colour contexts. */
.gs-toggle__thumb {
  box-sizing: border-box;
  block-size: 100%;
  aspect-ratio: 1;
  flex: none;

  position: relative;
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: 50%;
  background: var(--gs-color-ink);

  translate: 0;
  transition: translate var(--gs-motion-emphasis) var(--gs-motion-ease-pop);
}

/* On, the thumb is the accent's own ink with a tick in it, so the state
   reads by the thumb's end, the fill and a mark: never by colour alone. */
.gs-toggle[data-gs-active='true'] .gs-toggle__thumb {
  background: var(--gs-color-on-accent);
  border-color: var(--gs-color-on-accent);
}

.gs-toggle[data-gs-active='true'] .gs-toggle__thumb::after {
  content: '';
  position: absolute;
  inset-block-start: 22%;
  inset-inline-start: 36%;
  inline-size: 22%;
  block-size: 40%;
  border: solid var(--gs-color-interactive-solid);
  border-width: 0 var(--gs-stroke-ui) var(--gs-stroke-ui) 0;
  rotate: 45deg;
}

.gs-toggle[data-gs-active='true'] .gs-toggle__thumb {
  translate: calc(
    var(--gs-size-touch-min) + var(--gs-space-6) - var(--gs-size-control-small)
  );
}

/* The thumb is the only thing that moves, so a player who has asked for
   stillness gets the fill change and nothing else. The state is still
   readable: the thumb is at one end or the other, and the fill says which. */
@media (prefers-reduced-motion: reduce) {
  .gs-toggle__thumb { transition: none; }
}

/* A locked setting keeps its shape and shows a padlock, over the pill rather
   than in place of the thumb: the thumb is where the state is read from, and
   replacing it would hide the one thing the mark is qualifying. */
.gs-toggle__glyph {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gs-color-ink-secondary);
}

.gs-toggle__glyph svg {
  inline-size: var(--gs-size-icon-utility);
  block-size: var(--gs-size-icon-utility);
}

/* Not available at all: flat, per BDS-013, against locked's keeps-its-shape. */
.gs-toggle[data-gs-disabled='true'] .gs-toggle__control {
  background: var(--gs-color-disabled);
  border-color: var(--gs-color-disabled);
  cursor: default;
}

.gs-toggle[data-gs-disabled='true'] .gs-toggle__thumb {
  background: var(--gs-color-disabled-ink);
}

/* The words beside the pill. Specimen 4b sets them at DM Sans 700 15px; the
   body token is the interface face at 17px, which is the floor this library
   sets for anything a player reads as a sentence, so the label draws there
   and the 15px difference is a token request rather than a literal. */
.gs-toggle__label {
  min-inline-size: 0;
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-label-font-weight);
  line-height: var(--gs-type-title-line-height);
  color: var(--gs-color-ink);
  overflow-wrap: anywhere;
}

/* In the accessible name, not on screen: the label when the surface around it
   already says the words, and the locked state either way. */
.gs-toggle__announcement {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  white-space: nowrap;
  clip-path: inset(50%);
  border: 0;
}
